use std::cell::{Cell, RefCell};

fn main() {
    let c = Cell::new(1);          // for Copy values: get/set, no borrowing at all
    c.set(c.get() + 1);
    println!("{}", c.get());       // 2

    let r = RefCell::new(vec![1]); // for anything: borrow rules checked at RUN time
    r.borrow_mut().push(2);
    println!("{:?}", r.borrow());  // [1, 2]
}

